-- Seed img004.afi_intermediarios - corredores / agencias / agentes (Colmena).
-- Origen: files_migration/new_feature/img004/{schema,data}_afi_intermediarios.csv
--
-- Se usa para validar la existencia del intermediario del documento de comisiones
-- cuando el codigo es 03 (Corredor/Agencia). El codigo 01 (Consultor) se valida contra
-- img004.consultores. La llave de busqueda es numero_identificacion (solo digitos).
--
-- Idempotente: crea la tabla si falta y recarga el contenido completo. Sirve tanto para
-- el init del compat-db local como para aplicarlo a mano en un servidor con BD externa:
--   psql -U <usuario> -d img004 -f 46-seed-afi-intermediarios-img004.sql

CREATE TABLE IF NOT EXISTS public.afi_intermediarios (
    sr integer NOT NULL,
    fecha_insert timestamp with time zone DEFAULT now(),
    ramo varchar,
    regional varchar,
    numero_identificacion numeric,
    nit1 varchar,
    nit2 varchar,
    rui varchar,
    tipo varchar,
    sucursal varchar,
    nombre varchar,
    ciudad varchar,
    estado_autorizacion varchar DEFAULT 'AUTORIZADO'::character varying,
    usuario varchar,
    estado_registro boolean,
    tipo_documento varchar
);

-- Sin PRIMARY KEY sobre numero_identificacion a proposito: el volcado real trae
-- identificaciones repetidas (un mismo NIT con varias sucursales/regionales).
CREATE INDEX IF NOT EXISTS afi_intermediarios_num_ident_idx
    ON public.afi_intermediarios (numero_identificacion);

TRUNCATE public.afi_intermediarios;

